    <section class="card mb-4" aria-labelledby="playlists-heading">
        <div class="card-header d-flex align-items-center justify-content-between">
            <h2 class="h6 mb-0" id="playlists-heading"><button class="btn btn-sm btn-link text-body text-decoration-none p-0" type="button" data-bs-toggle="collapse" data-bs-target="#playlists-content" aria-expanded="true" aria-controls="playlists-content">Playlists <i class="bi bi-chevron-down" aria-hidden="true"></i></button></h2>
            <button class="btn btn-sm btn-outline-secondary" id="manage-playlists" type="button" aria-label="Manage playlists" title="Manage playlists"><i class="bi bi-sliders" aria-hidden="true"></i></button>
        </div>
        <div class="collapse show" id="playlists-content"><div class="card-body">
            <div id="playlist-options" class="d-flex flex-wrap gap-2 mb-3"><button class="btn btn-outline-info text-start" id="all-videos" type="button"><i class="bi bi-collection-play me-2" aria-hidden="true"></i>All videos</button>
            <div id="playlist-list" class="d-flex flex-wrap gap-2"></div></div>
            <button class="btn btn-sm btn-outline-secondary w-100 mt-3" id="open-sequence" type="button"><i class="bi bi-music-note-list me-2" aria-hidden="true"></i>Playlist sequence</button>
        </div>
    </div></section>
